        {
          "id": "day1_title",
          "component": "Text",
          "variant": "h3",
          "text": "Day 1: Torii Gates and Autumn Views (Tuesday, Nov 5)"
        },
        {
          "id": "day1_morning_title",
          "component": "Text",
          "variant": "h4",
          "text": "Morning Activity: Fushimi Inari Shrine"
        },
        {
          "id": "day1_morning_desc",
          "component": "Text",
          "text": "Begin your trip with an iconic Kyoto landmark. The thousands of vibrant red torii gates create a magical tunnel that kids will love exploring. You don't need to hike the entire mountain; the first 30-45 minutes of the path are the most impressive and fun for families."
        },
        {
          "id": "day1_morning_fee",
          "component": "Text",
          "variant": "caption",
          "text": "Entry Fee: Free."
        },
        {
          "id": "day1_morning_loc",
          "component": "Text",
          "variant": "caption",
          "text": "Location: Fushimi Ward. Accessible via JR Inari Station."
        },
        {
          "id": "day1_divider1",
          "component": "Divider"
        },
        {
          "id": "day1_afternoon_title",
          "component": "Text",
          "variant": "h4",
          "text": "Afternoon Activity: Tofuku-ji Temple"
        },
        {
          "id": "day1_afternoon_desc",
          "component": "Text",
          "text": "A short train ride from Fushimi Inari, this Zen temple is famous for its autumn foliage. The view from the Tsutenkyo Bridge is breathtaking in early November. The large temple grounds provide ample space for kids to walk around."
        },
        {
          "id": "day1_afternoon_fee",
          "component": "Text",
          "variant": "caption",
          "text": "Entry Fee: Approx. ¥1000 for access to Tsutenkyo Bridge & Kaisando Hall."
        },
        {
          "id": "day1_afternoon_loc",
          "component": "Text",
          "variant": "caption",
          "text": "Location: Higashiyama Ward. Accessible via JR Tofukuji Station."
        },
        {
          "id": "day1_divider2",
          "component": "Divider"
        },
        {
          "id": "day1_dinner_title",
          "component": "Text",
          "variant": "h4",
          "text": "Dinner Suggestion: Kyoto Ramen Koji (Ramen Street)"
        },
        {
          "id": "day1_dinner_desc",
          "component": "Text",
          "text": "Located on the 10th floor of the Kyoto Station building, this food court features ramen shops from all over Japan. It's a fun, casual, and delicious way to please everyone in the family."
        },
